VAL_LOSS=[(0, 0.6931), (25, 0.6531), (50, 0.6329), (75, 0.6352), (100, 0.6286), (125, 0.626), (150, 0.6183), (175, 0.6248), (200, 0.6161), (225, 0.6122), (250, 0.612), (275, 0.6112), (300, 0.6108), (314, 0.6096)]
